	public bool IsACoin
	{
		get
		{
			int num = this.type;
			if ((uint)(num - 71) <= 3u)
			{
				return true;
			}
			return false;
		}
	}

	public bool IsAir
	{
		get
		{
			if (this.type > 0)
			{
				return this.stack <= 0;
			}
			return true;
		}
	}

	public bool IsCurrency
	{
		get
		{
			if (this.type < 71 || this.type > 74)
			{
				return CustomCurrencyManager.IsCustomCurrency(this);
			}
			return true;
		}
	}

	public bool CanBeQuickUsed
	{
		get
		{
			if (this.IsAir)
			{
				return false;
			}
			bool? flag = ItemID.Sets.CanBeQuickusedOnGamepad[this.type];
			if (flag.HasValue)
			{
				return flag.Value;
			}
			if (this.healLife > 0)
			{
				return true;
			}
			if (this.healMana > 0)
			{
				return true;
			}
			if (this.buffType > 0 && this.buffTime > 0)
			{
				return true;
			}
			return false;
		}
	}

	public static string GetHoverName(Item item, int stack)
	{
		string text = item.AffixName();
		if (stack > 1)
		{
			text = text + " (" + stack + ")";
		}
		return text;
	}

	public static void StartCachingType(int t)
	{
		if (Item.cachedItemSpawnsByType[t] == -1)
		{
			Item.cachedItemSpawnsByType[t] = 0;
		}
	}

	public static void DropCache(IEntitySource reason, Vector2 pos, Vector2 spread, int t, bool stopCaching = true)
	{
		if (Item.cachedItemSpawnsByType[t] == -1)
		{
			return;
		}
		int num = Item.cachedItemSpawnsByType[t];
		Item.cachedItemSpawnsByType[t] = (stopCaching ? (-1) : 0);
		Item item = new Item();
		item.SetDefaults(t);
		while (num > 0)
		{
			int num2 = item.maxStack;
			if (num < num2)
			{
				num2 = num;
			}
			Item.NewItem(reason, (int)pos.X, (int)pos.Y, (int)spread.X, (int)spread.Y, t, num2);
			num -= num2;
		}
	}

