	public bool CanHavePrefixes()
	{
		return this.GetRollablePrefixes() != null;
	}

	public bool Prefix(int prefixWeWant)
	{
		bool rolledPrefixIsTopTier;
		return this.Prefix(prefixWeWant, out rolledPrefixIsTopTier);
	}

	public bool Prefix(int prefixWeWant, out bool rolledPrefixIsTopTier)
	{
		if (!WorldGen.isGeneratingOrLoadingWorld && Main.rand == null)
		{
			Main.rand = new UnifiedRandom();
		}
		rolledPrefixIsTopTier = false;
		if (prefixWeWant == 0)
		{
			return false;
		}
		if (!this.CanHavePrefixes())
		{
			return false;
		}
		if (prefixWeWant == -3)
		{
			return true;
		}
		float num = 0f;
		if (prefixWeWant == -2 || prefixWeWant == -1)
		{
			num = this.BestPrefixValue();
		}
		UnifiedRandom unifiedRandom = (WorldGen.isGeneratingOrLoadingWorld ? WorldGen.genRand : Main.rand);
		int rolledPrefix = prefixWeWant;
		float dmg = 1f;
		float kb = 1f;
		float spd = 1f;
		float size = 1f;
		float shtspd = 1f;
		float mcst = 1f;
		int crt = 0;
		int tagdmg = 0;
		int arpen = 0;
		float num2 = 0f;
		bool flag = true;
		while (flag)
		{
			flag = false;
			if (rolledPrefix == -1 && unifiedRandom.Next(4) == 0)
			{
				rolledPrefix = 0;
			}
			if (prefixWeWant < -1)
			{
				rolledPrefix = -1;
			}
			if ((rolledPrefix == -1 || rolledPrefix == -2 || rolledPrefix == -3) && !this.RollAPrefix(unifiedRandom, ref rolledPrefix))
			{
				return false;
			}
			if (prefixWeWant == -1 && PrefixID.Sets.ReducedNaturalChance[rolledPrefix] && unifiedRandom.Next(3) != 0)
			{
				rolledPrefix = 0;
			}
			if (prefixWeWant == -4)
			{
				rolledPrefix = 0;
			}
			if (!this.TryGetPrefixStatMultipliersForItem(rolledPrefix, out dmg, out kb, out spd, out size, out shtspd, out mcst, out crt, out tagdmg, out arpen, out num2))
			{
				flag = true;
				rolledPrefix = -1;
			}
			if (prefixWeWant == -2 && rolledPrefix == 0)
			{
				rolledPrefix = -1;
				flag = true;
			}
		}
		rolledPrefixIsTopTier = num2 == num;
		this.damage = (int)Math.Round((float)this.damage * dmg);
		this.useAnimation = (int)Math.Round((float)this.useAnimation * spd);
		this.useTime = (int)Math.Round((float)this.useTime * spd);
		this.reuseDelay = (int)Math.Round((float)this.reuseDelay * spd);
		this.mana = (int)Math.Round((float)this.mana * mcst);
		this.knockBack *= kb;
		this.scale *= size;
		this.shootSpeed *= shtspd;
		this.crit += crt;
		this.bonusTagDamage += tagdmg;
		this.armorPenetration += arpen;
		if ((double)num2 >= 1.2)
		{
			this.rare += 2;
		}
		else if ((double)num2 >= 1.05)
		{
			this.rare++;
		}
		else if ((double)num2 <= 0.8)
		{
			this.rare -= 2;
		}
		else if ((double)num2 <= 0.95)
		{
			this.rare--;
		}
		if (this.rare > -11)
		{
			if (this.rare < -1)
			{
				this.rare = -1;
			}
			if (this.rare > 11)
			{
				this.rare = 11;
			}
		}
		num2 *= num2;
		this.value = (int)((float)this.value * num2);
		this.prefix = (byte)rolledPrefix;
		return true;
	}

	public bool CanRollPrefix(int prefix)
	{
		int[] rollablePrefixes = this.GetRollablePrefixes();
		if (rollablePrefixes == null)
		{
			return false;
		}
		for (int i = 0; i < rollablePrefixes.Length; i++)
		{
			if (rollablePrefixes[i] == prefix)
			{
				return true;
			}
		}
		return false;
	}

	public int GetVisualCritChance(Player player)
	{
		int num = this.crit;
		if (this.type == 2269 && player.revolverCritChanceBonus > 0)
		{
			num = (int)MathHelper.Clamp(num + player.revolverCritChanceBonus, 0f, 100f);
		}
		return num;
	}

	public Color GetPopupRarityColor()
	{
		return Item.GetPopupRarityColor(this.rare);
	}

	public static Color GetPopupRarityColor(int itemRarity)
	{
		if (itemRarity == 1)
		{
			return new Color(150, 150, 255);
		}
		if (itemRarity == 2)
		{
			return new Color(150, 255, 150);
		}
		if (itemRarity == 3)
		{
			return new Color(255, 200, 150);
		}
		if (itemRarity == 4)
		{
			return new Color(255, 150, 150);
		}
		if (itemRarity == 5)
		{
			return new Color(255, 150, 255);
		}
		if (itemRarity == -11)
		{
			return new Color(255, 175, 0);
		}
		if (itemRarity == -1)
		{
			return new Color(130, 130, 130);
		}
		if (itemRarity == 6)
		{
			return new Color(210, 160, 255);
		}
		if (itemRarity == 7)
		{
			return new Color(150, 255, 10);
		}
		if (itemRarity == 8)
		{
			return new Color(255, 255, 10);
		}
		if (itemRarity == 9)
		{
			return new Color(5, 200, 255);
		}
		if (itemRarity == 10)
		{
			return new Color(255, 40, 100);
		}
		if (itemRarity >= 11)
		{
			return new Color(180, 40, 255);
		}
		return Color.White;
	}

