			break;
		case 48:
			spd = 1.2f;
			break;
		case 49:
			spd = 1.08f;
			break;
		case 50:
			dmg = 0.8f;
			spd = 1.15f;
			break;
		case 51:
			kb = 0.9f;
			spd = 0.9f;
			dmg = 1.05f;
			crt = 2;
			break;
		}
		value = 1f * dmg * (2f - spd) * (2f - mcst) * size * kb * shtspd * (1f + (float)crt * 0.02f) * (1f + (float)arpen * 0.015f) * (1f + (float)tagdmg * 0.03f);
		if (rolledPrefix == 62 || rolledPrefix == 69 || rolledPrefix == 73 || rolledPrefix == 77)
		{
			value *= 1.05f;
		}
		if (rolledPrefix == 63 || rolledPrefix == 70 || rolledPrefix == 74 || rolledPrefix == 78 || rolledPrefix == 67)
		{
			value *= 1.1f;
		}
		if (rolledPrefix == 64 || rolledPrefix == 71 || rolledPrefix == 75 || rolledPrefix == 79 || rolledPrefix == 66)
		{
			value *= 1.15f;
		}
		if (rolledPrefix == 65 || rolledPrefix == 72 || rolledPrefix == 76 || rolledPrefix == 80 || rolledPrefix == 68)
		{
			value *= 1.2f;
		}
		if (dmg != 1f && Math.Round((float)this.damage * dmg) == (double)this.damage)
		{
			return false;
		}
		if (spd != 1f && Math.Round((float)this.useAnimation * spd) == (double)this.useAnimation)
		{
			return false;
		}
		if (mcst != 1f && Math.Round((float)this.mana * mcst) == (double)this.mana)
		{
			return false;
		}
		if (kb != 1f && this.knockBack == 0f)
		{
			return false;
		}
		return true;
	}

	public float BestPrefixValue()
	{
		int[] rollablePrefixes = this.GetRollablePrefixes();
		if (rollablePrefixes == null)
		{
			return 0f;
		}
		float num = 0f;
		int[] array = rollablePrefixes;
		foreach (int rolledPrefix in array)
		{
			if (this.TryGetPrefixStatMultipliersForItem(rolledPrefix, out var _, out var _, out var _, out var _, out var _, out var _, out var _, out var _, out var _, out var val))
			{
				num = Math.Max(num, val);
			}
		}
		return num;
	}

	public int[] GetRollablePrefixes()
	{
		_ = this.type;
		if (PrefixLegacy.ItemSets.SwordsHammersAxesPicks[this.type])
		{
			return PrefixLegacy.Prefixes.PrefixesForSwords;
		}
		if (PrefixLegacy.ItemSets.SpearsMacesChainsawsDrillsPunchCannon[this.type])
		{
			return PrefixLegacy.Prefixes.PrefixesForSpears;
		}
		if (PrefixLegacy.ItemSets.GunsBows[this.type])
		{
			return PrefixLegacy.Prefixes.PrefixesForGunsBows;
		}
		if (PrefixLegacy.ItemSets.Magic[this.type])
		{
			return PrefixLegacy.Prefixes.PrefixesForMagic;
		}
		if (PrefixLegacy.ItemSets.Summon[this.type])
		{
			return PrefixLegacy.Prefixes.PrefixesForSummons;
		}
		if (PrefixLegacy.ItemSets.BoomerangsChakrams[this.type])
		{
			return PrefixLegacy.Prefixes.PrefixesForBoomeransAndChakrums;
		}
		if (PrefixLegacy.ItemSets.ItemsThatCanHaveLegendary2[this.type])
		{
			return PrefixLegacy.Prefixes.PrefixesForBoomeransAndChakrums_TerrarianYoyo;
		}
		if (this.IsAPrefixableAccessory())
		{
			return PrefixLegacy.Prefixes.PrefixesForAccessories;
		}
		return null;
	}

	private bool RollAPrefix(UnifiedRandom random, ref int rolledPrefix)
	{
		int[] rollablePrefixes = this.GetRollablePrefixes();
		if (rollablePrefixes == null)
		{
			return false;
		}
		rolledPrefix = rollablePrefixes[random.Next(rollablePrefixes.Length)];
		return true;
	}

	public bool IsAPrefixableAccessory()
	{
		if (this.accessory && !this.vanity)
		{
			return ItemID.Sets.CanGetPrefixes[this.type];
		}
		return false;
	}

	public bool CanBeEquipped()
	{
		if (this.headSlot < 0 && this.bodySlot < 0 && this.legSlot < 0 && !this.accessory && (this.shoot <= 0 || !Main.projHook[this.shoot]) && this.mountType < 0)
		{
			if (this.buffType > 0)
			{
				if (!Main.vanityPet[this.buffType])
				{
					return Main.lightPet[this.buffType];
				}
				return true;
			}
			return false;
		}
		return true;
	}

	public bool OnlyNeedOneInInventory()
	{
		bool? flag = ItemID.Sets.OnlyNeedOneInInventoryOverride[this.type];
		if (flag.HasValue)
		{
			return flag.Value;
		}
		if (!this.consumable)
		{
			if (this.useStyle == 0)
			{
				return this.CanBeEquipped();
			}
			return true;
		}
		return false;
	}

	public string AffixName()
	{
		if (this.prefix <= 0 || this.prefix >= Lang.prefix.Length)
		{
			return this.Name;
		}
		return Lang.GetPrefixedItemName(this.type, this.prefix);
	}

	public void RebuildTooltip()
	{
		if (this.type >= 0)
		{
			this.ToolTip = Lang.GetTooltip(this.type);
		}
	}

