	public void DefaultToGolfBall(int projid)
	{
		this.shoot = projid;
		this.useStyle = 1;
		this.shootSpeed = 12f;
		this.width = 18;
		this.height = 20;
		this.UseSound = SoundID.Item1;
		this.useAnimation = 15;
		this.useTime = 15;
		this.noUseGraphic = true;
		this.noMelee = true;
		this.value = 0;
		this.accessory = true;
		this.SetShopValues(ItemRarityColor.Green2, Item.buyPrice(0, 1));
		this.hasVanityEffects = true;
	}

