	public void DefaultToBanner(int tileStyleToPlace = 0)
	{
		this.SetShopValues(ItemRarityColor.Blue1, 1000);
		this.DefaultToPlaceableTile((ushort)91, tileStyleToPlace);
		this.width = 10;
		this.height = 24;
	}

	public void DefaultToMonolith(int tileIDToPlace, int tileStyleToPlace = 0)
	{
		this.DefaultToPlaceableTile(tileIDToPlace, tileStyleToPlace);
		this.width = 22;
		this.height = 32;
		this.accessory = true;
		this.vanity = true;
	}

	public void DefaultToBomb(int projectileID, float throwSpeed)
	{
		this.useStyle = 1;
		this.shootSpeed = throwSpeed;
		this.shoot = projectileID;
		this.width = 8;
		this.height = 28;
		this.consumable = true;
		this.UseSound = SoundID.Item1;
		this.useAnimation = 40;
		this.useTime = 40;
		this.noUseGraphic = true;
		this.noMelee = true;
	}

	public void DefaultToVoiceOverrideAccessory(sbyte voiceOverrideID)
	{
		this.useStyle = 4;
		this.UseSound = null;
		this.useTurn = false;
		this.useAnimation = 17;
		this.useTime = 17;
		this.width = 24;
		this.height = 24;
		this.accessory = true;
		this.vanity = true;
		this.voiceSlot = voiceOverrideID;
	}

	public void DefaultToSolution(int projectileId)
	{
		this.shoot = projectileId - 145;
		this.ammo = AmmoID.Solution;
		this.width = 10;
		this.height = 12;
		this.value = Item.buyPrice(0, 0, 15);
		this.rare = 3;
		this.consumable = true;
	}

	public void DefaultToWhip(int projectileId, int dmg, float kb, float shootspeed, int animationTotalTime = 30)
	{
		this.autoReuse = false;
		this.useStyle = 1;
		this.useAnimation = animationTotalTime;
		this.useTime = animationTotalTime;
		this.width = 18;
		this.height = 18;
		this.shoot = projectileId;
		this.UseSound = SoundID.Item152;
		this.noMelee = true;
		this.summon = true;
		this.noUseGraphic = true;
		this.damage = dmg;
		this.knockBack = kb;
		this.shootSpeed = shootspeed;
	}

	public void DefaultToKite(int projId)
	{
		this.width = 20;
		this.height = 28;
		this.DefaultToThrownWeapon(projId, 15, 8f);
		this.consumable = false;
		this.ranged = false;
		this.noUseGraphic = true;
		this.SetShopValues(ItemRarityColor.Blue1, Item.buyPrice(0, 2));
		this.createTile = 723;
	}

	public void ChangeItemType(int to)
	{
		bool flag = this.favorited;
		byte prefixWeWant = this.prefix;
		int num = this.stack;
		this.SetDefaults(to);
		this.Prefix(prefixWeWant);
		this.favorited = flag;
		this.stack = num;
	}

	public bool IsConsideredSameItemAsType(int compareType)
	{
		switch (this.type)
		{
		case 5324:
		case 5329:
		case 5330:
			if (compareType != 5324 && compareType != 5329)
			{
				return compareType == 5330;
			}
			return true;
		case 4346:
		case 5391:
			if (compareType != 4346)
			{
				return compareType == 5391;
			}
			return true;
		case 4131:
		case 5325:
			if (compareType != 4131)
			{
				return compareType == 5325;
			}
			return true;
		case 5323:
		case 5455:
			if (compareType != 5323)
			{
				return compareType == 5455;
			}
			return true;
		case 4767:
		case 5453:
			if (compareType != 4767)
			{
				return compareType == 5453;
			}
			return true;
		case 5309:
		case 5454:
			if (compareType != 5309)
			{
				return compareType == 5454;
			}
			return true;
		case 5358:
		case 5359:
		case 5360:
		case 5361:
		case 5437:
			if (compareType != 5358 && compareType != 5360 && compareType != 5359 && compareType != 5361)
			{
				return compareType == 5437;
			}
			return true;
		case 2611:
		case 5526:
			if (compareType != 2611)
			{
				return compareType == 5526;
			}
			return true;
		default:
			return this.type == compareType;
		}
	}

	public void DefaultToVanitypet(int projId, int buffID)
	{
		this.damage = 0;
		this.useStyle = 1;
		this.width = 16;
		this.height = 30;
		this.UseSound = SoundID.Item2;
		this.useAnimation = 20;
		this.useTime = 20;
		this.rare = 3;
		this.noMelee = true;
		this.value = Item.sellPrice(0, 2);
		this.buffType = buffID;
		this.shoot = projId;
	}

	public static bool IsAGolfingItem(Item item)
	{
		if (ProjectileID.Sets.IsAGolfBall[item.shoot])
		{
			return true;
		}
		int num = item.type;
		if (num == 4039 || (uint)(num - 4092) <= 3u || (uint)(num - 4587) <= 11u)
		{
			return true;
		}
		return false;
	}

	private void DefaultToSeaShell()
	{
		this.useStyle = 1;
		this.autoReuse = true;
		this.useAnimation = 15;
		this.useTime = 10;
		this.consumable = true;
		this.createTile = 324;
		this.width = 22;
		this.height = 22;
		switch (this.type)
		{
