	public static Color GetPhaseColor(int projectileType, bool drawColor = false)
	{
		if (Item._phaseColors == null)
		{
			Item._phaseColors = new Color[9]
			{
				Item.GetPhaseColorDirect(1059),
				Item.GetPhaseColorDirect(1060),
				Item.GetPhaseColorDirect(1061),
				Item.GetPhaseColorDirect(1062),
				Item.GetPhaseColorDirect(1063),
				Item.GetPhaseColorDirect(1064),
				Item.GetPhaseColorDirect(1071),
				Item.GetPhaseColorDirect(1075),
				Item.GetPhaseColorDirect(1059)
			};
		}
		switch (projectileType)
		{
		case 1059:
		case 1065:
			return Item._phaseColors[0];
		case 1060:
		case 1066:
			return Item._phaseColors[1];
		case 1061:
		case 1067:
			return Item._phaseColors[2];
		case 1062:
		case 1068:
			return Item._phaseColors[3];
		case 1063:
		case 1069:
			return Item._phaseColors[4];
		case 1064:
		case 1070:
			return Item._phaseColors[5];
		case 1071:
		case 1072:
			return Item._phaseColors[6];
		case 1075:
		case 1076:
			return Item._phaseColors[7];
		case 1101:
		case 1102:
		{
			Color result = Utils.MultiLerp(Main.LocalPlayer.miscCounterNormalized, Item._phaseColors);
			if (drawColor)
			{
				float num = 0.5f;
				result.A = (byte)(255f * num);
			}
			return result;
		}
		default:
			return Color.White;
		}
	}

	private static Color GetPhaseColorDirect(int projectileType)
	{
		float num = 1f;
		float num2 = 1f;
		float num3 = 1f;
		switch (projectileType)
		{
		case 1059:
		case 1065:
			num *= 0.1f;
			num2 *= 0.5f;
			num3 *= 1.2f;
			break;
		case 1060:
		case 1066:
			num *= 1f;
			num2 *= 0.2f;
			num3 *= 0.1f;
			break;
		case 1061:
		case 1067:
			num *= 0.1f;
			num2 *= 1f;
			num3 *= 0.2f;
			break;
		case 1062:
		case 1068:
			num *= 0.8f;
			num2 *= 0.1f;
			num3 *= 1f;
			break;
		case 1063:
		case 1069:
			num *= 0.8f;
			num2 *= 0.9f;
			num3 *= 1f;
			break;
		case 1064:
		case 1070:
			num *= 0.8f;
			num2 *= 0.8f;
			num3 *= 0f;
			break;
		case 1071:
		case 1072:
			num *= 0.9f;
			num2 *= 0.5f;
			num3 *= 0f;
			break;
		case 1075:
		case 1076:
			num *= 1.05f;
			num2 *= 0.1f;
			num3 *= 0.4f;
			break;
		}
		return new Color(num, num2, num3);
	}

	public Color GetAlpha(Color newColor)
	{
		if (ItemID.Sets.BossBag[this.type])
		{
			return Color.Lerp(newColor, Color.White, 0.4f);
