		switch (this.type)
		{
		case 1326:
		case 5335:
			return Color.Lerp(newColor, Color.White, 0.75f);
		case 5043:
			return new Color(255, 255, 255, newColor.A - this.alpha);
		case 3065:
		case 4956:
		case 5669:
