		case 502:
		case 4988:
			return new Color(255, 255, 255, 150);
		case 51:
			return new Color(255, 255, 255, 0);
		case 1260:
			return new Color(255, 255, 255, 175);
		case 1446:
		case 1506:
		case 1507:
		case 1543:
		case 1544:
		case 1545:
			return new Color(newColor.R, newColor.G, newColor.B, Main.gFade);
		case 198:
		case 199:
		case 200:
		case 201:
		case 202:
		case 203:
		case 3764:
		case 3765:
		case 3766:
		case 3767:
		case 3768:
		case 3769:
		case 4258:
		case 4259:
		case 5535:
