			return Color.White;
		case 2763:
		case 2764:
		case 2765:
		case 2782:
		case 2783:
		case 2784:
		case 2785:
		case 2786:
		case 3522:
			return new Color(250, 250, 250, 255 - this.alpha);
		case 3191:
			return new Color(250, 250, 250, 200);
		case 3822:
			return Color.Lerp(Color.White, newColor, 0.5f) * ((255f - (float)this.alpha) / 255f);
		case 4143:
			return Color.Lerp(Color.White, newColor, 0f) * ((255f - (float)this.alpha) / 255f);
		case 4354:
		case 4377:
		case 4378:
		case 4389:
		case 5127:
		case 5128:
		{
			Color color = default(Color);
			color = this.type switch
			{
				4377 => new Color(50, 255, 50, 200), 
				4378 => new Color(50, 200, 255, 255), 
				4389 => new Color(255, 50, 125, 200), 
				5127 => new Color(150, 50, 250, 200), 
				5128 => new Color(Main.DiscoR, Main.DiscoG, Main.DiscoB, 200), 
				_ => new Color(255, 150, 150, 200), 
			};
			if (newColor.R > color.R)
			{
				color.R = newColor.R;
			}
			if (newColor.G > color.G)
			{
				color.G = newColor.G;
			}
			if (newColor.B > color.B)
			{
				color.B = newColor.B;
			}
			if (newColor.A > color.A)
			{
				color.A = newColor.A;
			}
			return color;
		}
		default:
		{
			float num = (float)(255 - this.alpha) / 255f;
			int r = (int)((float)(int)newColor.R * num);
			int g = (int)((float)(int)newColor.G * num);
			int b = (int)((float)(int)newColor.B * num);
			int num2 = newColor.A - this.alpha;
			if (num2 < 0)
			{
				num2 = 0;
			}
			if (num2 > 255)
			{
				num2 = 255;
			}
			return new Color(r, g, b, num2);
		}
		}
	}

	public Color GetColor(Color newColor)
	{
		int num = this.color.R - (255 - newColor.R);
		int num2 = this.color.G - (255 - newColor.G);
		int num3 = this.color.B - (255 - newColor.B);
		int num4 = this.color.A - (255 - newColor.A);
		if (num < 0)
		{
			num = 0;
		}
		if (num > 255)
		{
			num = 255;
		}
		if (num2 < 0)
		{
			num2 = 0;
		}
		if (num2 > 255)
		{
			num2 = 255;
		}
		if (num3 < 0)
		{
			num3 = 0;
		}
		if (num3 > 255)
		{
			num3 = 255;
		}
		if (num4 < 0)
		{
			num4 = 0;
		}
		if (num4 > 255)
		{
			num4 = 255;
		}
		return new Color(num, num2, num3, num4);
	}

