	public bool CanShimmer()
	{
		int shimmerEquivalentType = this.GetShimmerEquivalentType();
		if (ShimmerTransforms.IsItemTransformLocked(shimmerEquivalentType))
		{
			return false;
		}
		if (shimmerEquivalentType == 560 && Main.slimeRain)
		{
			return false;
		}
		if ((shimmerEquivalentType != 4986 || NPC.unlockedSlimeRainbowSpawn) && ShimmerTransforms.GetTransformToItem(shimmerEquivalentType) <= 0 && !ShimmerTransforms.IsItemDecraftableAndIsDecraftUnlocked(this) && !ItemID.Sets.CommonCoin[shimmerEquivalentType])
		{
			return this.makeNPC > 0;
		}
		return true;
	}

	public int FindDecraftAmount()
	{
		int decraftingRecipeIndex = ShimmerTransforms.GetDecraftingRecipeIndex(this.GetShimmerEquivalentType(forDecrafting: true));
		if (decraftingRecipeIndex < 0)
		{
			return -1;
		}
		return this.stack / Main.recipe[decraftingRecipeIndex].createItem.stack;
	}

	public int GetShimmerEquivalentType(bool forDecrafting = false)
	{
		if (forDecrafting && ItemID.Sets.ShimmerCountsAsItemForDecraft[this.type] != -1)
		{
			return ItemID.Sets.ShimmerCountsAsItemForDecraft[this.type];
		}
		if (ItemID.Sets.ShimmerCountsAsItem[this.type] != -1)
		{
			return ItemID.Sets.ShimmerCountsAsItem[this.type];
		}
		return this.type;
	}

	public void FixAgainstExploit()
	{
		if (ItemID.Sets.ItemsThatShouldNotBeInInventory[this.type])
		{
			this.TurnToAir();
			return;
		}
		if (this.stack > this.maxStack)
		{
			this.stack = this.maxStack;
		}
		if (this.prefix != 0 && !this.CanRollPrefix(this.prefix))
		{
			this.ResetPrefix();
		}
	}

