	public bool TryAddStack(int itemType, ref int amountLeftToAdd)
	{
		if (amountLeftToAdd < 0)
		{
			amountLeftToAdd = 0;
		}
		if (this.IsAir)
		{
			this.SetDefaults(itemType);
			amountLeftToAdd -= (this.stack = Math.Min(amountLeftToAdd, this.maxStack));
			return true;
		}
		if (this.type != itemType)
		{
			return false;
		}
		if (this.stack >= this.maxStack)
		{
			return false;
		}
		int max = this.maxStack - this.stack;
		int num = Utils.Clamp(amountLeftToAdd, 0, max);
		if (num <= 0)
		{
			return false;
		}
		this.stack += num;
		amountLeftToAdd -= num;
		return true;
	}

	public bool CanPassivelyStackInWorld()
	{
		if (this.maxStack == 1)
		{
			return false;
		}
		bool? flag = ItemID.Sets.CanPassivelyStackInWorldOverride[this.type];
		if (flag.HasValue)
		{
			return flag.Value;
		}
		if (this.OnlyNeedOneInInventory())
		{
			return false;
		}
		if (this.createTile < 0 && this.createWall <= 0 && (this.ammo <= 0 || this.notAmmo) && !this.consumable && this.dye <= 0 && !this.PaintOrCoating)
		{
			return this.material;
		}
		return true;
	}

	public static Rectangle GetDrawHitbox(int type, Player user)
	{
		if (Main.dedServ)
		{
			return Rectangle.Empty;
		}
		Main.instance.LoadItem(type);
		if (ItemID.Sets.IsFood[type])
		{
			return TextureAssets.Item[type].Frame(1, 3, 0, 1);
		}
		switch (type)
		{
		case 75:
			return TextureAssets.Item[type].Frame(1, 8);
		case 520:
		case 521:
		case 547:
		case 548:
		case 549:
		case 575:
		case 3453:
		case 3454:
		case 3455:
		case 3580:
		case 3581:
		case 4068:
		case 4069:
		case 4070:
			return TextureAssets.Item[type].Frame(1, 4);
		default:
			if (Main.itemAnimations[type] != null)
			{
				return Main.itemAnimations[type].GetFrame(TextureAssets.Item[type].Value);
			}
			return TextureAssets.Item[type].Frame();
		}
	}

