	public static int NewItem(IEntitySource source, int X, int Y, int Width, int Height, int Type, int Stack = 1, bool noBroadcast = false, int pfix = 0, bool noGrabDelay = false)
	{
		if (WorldGen.isGeneratingOrLoadingWorld)
		{
			return 0;
		}
		if (Stack <= 0)
		{
			return 400;
		}
		if (Main.rand == null)
		{
			Main.rand = new UnifiedRandom();
		}
		if (Main.tenthAnniversaryWorld)
		{
			if (Type == 58)
			{
				Type = Main.rand.NextFromList(new short[3] { 1734, 1867, 58 });
			}
			if (Type == 184)
			{
				Type = Main.rand.NextFromList(new short[3] { 1735, 1868, 184 });
			}
		}
		else if (Main.halloween && Main.xMas)
		{
			if (Type == 58)
			{
				Type = Main.rand.NextFromList(new short[2] { 1734, 1867 });
			}
			if (Type == 184)
			{
				Type = Main.rand.NextFromList(new short[2] { 1735, 1868 });
			}
		}
		else
		{
			if (Main.halloween)
			{
				if (Type == 58)
				{
					Type = 1734;
				}
				if (Type == 184)
				{
					Type = 1735;
				}
			}
			if (Main.xMas)
			{
				if (Type == 58)
				{
					Type = 1867;
				}
				if (Type == 184)
				{
					Type = 1868;
				}
			}
		}
		if (Type > 0 && Item.cachedItemSpawnsByType[Type] != -1)
		{
			Item.cachedItemSpawnsByType[Type] += Stack;
			return 400;
		}
		int num = ((Main.netMode == 1) ? 400 : Item.PickAnItemSlotToSpawnItemOn());
		if (Main.item[num].active && num != 400 && Main.netMode == 2)
		{
			NetMessage.SendData(151, -1, -1, null, num);
		}
		Main.timeItemSlotCannotBeReusedFor[num] = 0;
		EmergencyStacking.ClearPendingTransfersInvolving(Main.item[num]);
		Main.item[num] = new WorldItem();
		WorldItem worldItem = Main.item[num];
		worldItem.SetDefaults(Type);
		worldItem.whoAmI = num;
		worldItem.Prefix(pfix);
		worldItem.stack = Stack;
		worldItem.position.X = X + Width / 2 - worldItem.width / 2;
		worldItem.position.Y = Y + Height / 2 - worldItem.height / 2;
		worldItem.wet = Collision.WetCollision(worldItem.position, worldItem.width, worldItem.height);
		worldItem.velocity.X = (float)Main.rand.Next(-30, 31) * 0.1f;
		worldItem.velocity.Y = (float)Main.rand.Next(-40, -15) * 0.1f;
		if (Type == 859 || Type == 4743)
		{
			worldItem.velocity *= 0f;
		}
		if (Type == 520 || Type == 521 || (worldItem.type >= 0 && ItemID.Sets.NebulaPickup[worldItem.type]))
		{
			worldItem.velocity.X = (float)Main.rand.Next(-30, 31) * 0.1f;
			worldItem.velocity.Y = (float)Main.rand.Next(-30, 31) * 0.1f;
		}
		worldItem.timeSinceItemSpawned = ItemID.Sets.OverflowProtectionTimeOffset[worldItem.type];
		if (ItemSlot.Options.HighlightNewItems && worldItem.type >= 0 && !ItemID.Sets.NeverAppearsAsNewInInventory[worldItem.type])
		{
			worldItem.newAndShiny = true;
		}
		if (Main.netMode == 2 && !noBroadcast)
		{
			NetMessage.SendData(21, -1, -1, null, num, noGrabDelay.ToInt());
		}
		else if (Main.netMode == 0)
		{
			worldItem.playerIndexTheItemIsReservedFor = Main.myPlayer;
		}
		return num;
	}

	private static int PickAnItemSlotToSpawnItemOn()
	{
		int num = 400;
		int num2 = -1;
		int num3 = Item.PickupReplacementTime;
		for (int i = 0; i < 400; i++)
		{
			WorldItem worldItem = Main.item[i];
			if (!worldItem.active && Main.timeItemSlotCannotBeReusedFor[i] == 0)
			{
				num = i;
				break;
			}
			if (worldItem.active && ItemID.Sets.IsAPickup[worldItem.type] && worldItem.timeSinceItemSpawned > num3)
			{
				num3 = worldItem.timeSinceItemSpawned;
				num2 = i;
			}
		}
		int num4 = 400;
		if (Main.netMode == 2)
		{
			num4 -= Item.SlotsRemainingBeforeEmergencyStackingInMultiplayer;
		}
		if (num >= num4)
		{
			if (num2 >= 0)
			{
				return num2;
			}
			if (EmergencyStacking.EmergencyStackItemsToMakeSpace(out var freeSlot))
			{
				return freeSlot;
			}
		}
		if (num != 400)
		{
			return num;
		}
		int num5 = 0;
		for (int j = 0; j < 400; j++)
		{
			if (Main.timeItemSlotCannotBeReusedFor[j] == 0 && !Main.item[j].instanced && Main.item[j].timeSinceItemSpawned > num5)
			{
				num5 = Main.item[j].timeSinceItemSpawned;
				num = j;
			}
		}
		if (num != 400)
		{
			return num;
		}
		for (int k = 0; k < 400; k++)
		{
			if (Main.item[k].timeSinceItemSpawned - Main.timeItemSlotCannotBeReusedFor[k] > num5)
			{
				num5 = Main.item[k].timeSinceItemSpawned - Main.timeItemSlotCannotBeReusedFor[k];
				num = k;
			}
		}
		return num;
	}

	public Item Clone()
	{
		return (Item)base.MemberwiseClone();
	}

	public Item DeepClone()
	{
		return (Item)base.MemberwiseClone();
	}

	public bool IsNotTheSameAs(Item compareItem)
	{
		if (this.type == compareItem.type && this.stack == compareItem.stack)
		{
			return this.prefix != compareItem.prefix;
		}
		return true;
	}

	public bool IsNetStateDifferent(Item compareItem)
	{
		if (!this.IsNotTheSameAs(compareItem))
		{
			return this.favorited != compareItem.favorited;
		}
		return true;
	}

	public static bool CanStack(Item item1, Item item2)
	{
		if (item1.type == item2.type)
		{
			return item1.prefix == item2.prefix;
		}
		return false;
	}

